using System.Xml.Linq;
using Spectre.Console;
using Spectre.Console.Rendering;

namespace DotPad.Cli;

// TODO.md #40 follow-up (user: "хочу чтобы html выводился красиво, ... Spectre.Console"):
// DumpRenderer's HTML is generated by this same codebase from a small, fixed vocabulary of elements
// and CSS classes (dp-label/dp-null/dp-string/dp-table/...), never arbitrary user-authored markup —
// so unlike general HTML, it's well-formed enough to parse directly as XML (no HTML parser needed),
// and its structure maps cleanly onto Spectre.Console renderables: a dp-table becomes a real Table
// (nested tables inside a cell — e.g. a property whose value is itself a collection — render as
// nested Spectre tables for free, since Table itself is an IRenderable), dp-* spans become colored
// Markup.
internal static class DumpHtmlSpectreRenderer
{
    public static IRenderable Render(string html)
    {
        // DumpRenderer emits exactly one entity outside its own Encode() (which only ever produces
        // the five entities XML understands natively) — &mdash; in RenderEnumerable's item-count
        // line — so this one substitution is enough to make the payload valid XML.
        var root = XElement.Parse("<root>" + html.Replace("&mdash;", "—") + "</root>");
        return Combine(root.Nodes().Select(RenderNode));
    }

    private static IRenderable? RenderNode(XNode node)
    {
        if (node is XText text)
            return string.IsNullOrWhiteSpace(text.Value) ? null : new Markup(Markup.Escape(text.Value));

        if (node is not XElement el) return null;
        var cls = (string?)el.Attribute("class") ?? "";

        switch (el.Name.LocalName)
        {
            case "span":
                return StyledText(cls, el.Value) ?? new Markup(Markup.Escape(el.Value));
            case "div" when cls.Contains("dp-label"):
                return new Markup($"[bold underline]{Markup.Escape(el.Value)}[/]");
            case "div" when cls.Contains("dp-type"):
                return new Markup($"[bold yellow]{Markup.Escape(el.Value)}[/]");
            case "div" when cls.Contains("dp-count"):
                return new Markup($"[grey italic]{Markup.Escape(el.Value)}[/]");
            case "table":
                return RenderTable(el);
            case "details":
                // No interactivity in a terminal — just render the (possibly collapsed) content
                // directly, skipping the "(click to expand)" <summary>.
                return Combine(el.Elements().Where(c => c.Name.LocalName != "summary").Select(RenderNode));
            case "tr" or "td" or "th" or "thead" or "tbody" or "summary":
                return null; // handled directly by RenderTable/the "details" case above
            default:
                // An unrecognized wrapper — e.g. DumpContainer's <div data-dp-id="..."> — pass
                // through to its children rather than silently dropping the content.
                return Combine(el.Nodes().Select(RenderNode));
        }
    }

    private static IRenderable? StyledText(string cls, string text) => cls switch
    {
        _ when cls.Contains("dp-null") => new Markup("[grey]null[/]"),
        _ when cls.Contains("dp-string") => new Markup($"[green]{Markup.Escape(text)}[/]"),
        _ when cls.Contains("dp-bool") => new Markup($"[fuchsia]{Markup.Escape(text)}[/]"),
        _ when cls.Contains("dp-datetime") => new Markup($"[yellow]{Markup.Escape(text)}[/]"),
        _ when cls.Contains("dp-enum") => new Markup($"[blue]{Markup.Escape(text)}[/]"),
        _ when cls.Contains("dp-number") => new Markup($"[cyan1]{Markup.Escape(text)}[/]"),
        _ when cls.Contains("dp-error") => new Markup($"[bold red]{Markup.Escape(text)}[/]"),
        _ when cls.Contains("dp-truncated") => new Markup($"[grey italic]{Markup.Escape(text)}[/]"),
        _ when cls.Contains("dp-propname") => new Markup($"[bold]{Markup.Escape(text)}[/]"),
        _ => null,
    };

    private static Table RenderTable(XElement tableEl)
    {
        var table = new Table { Border = TableBorder.Rounded };

        var headerCells = tableEl.Element("thead")?.Elements("tr").FirstOrDefault()?.Elements("th").ToList()
            ?? [];
        foreach (var th in headerCells)
            table.AddColumn(new TableColumn(Markup.Escape(th.Value)));
        if (headerCells.Count == 0)
            table.AddColumn(new TableColumn(string.Empty)); // never happens today, but AddRow needs >=1 column

        var columnCount = Math.Max(headerCells.Count, 1);
        foreach (var tr in tableEl.Element("tbody")?.Elements("tr") ?? Enumerable.Empty<XElement>())
        {
            // A repeated mid-table header row (DumpRenderer.MaybeRepeatHeader) is <tr><th>...</tr>,
            // not <td> — Spectre has no notion of a repeated header mid-table, so it's dropped; the
            // original header stays visible above regardless of how long the table is.
            var cells = tr.Elements("td").Select(RenderCellContent).ToList();
            if (cells.Count == 0) continue;

            // A colspan truncation/null row ("… N more", "null") is a single <td> standing in for
            // every column — pad it out so AddRow gets one cell per column instead of throwing.
            while (cells.Count < columnCount) cells.Add(new Markup(string.Empty));
            table.AddRow(cells);
        }

        return table;
    }

    private static IRenderable RenderCellContent(XElement td)
    {
        var cls = (string?)td.Attribute("class") ?? "";
        // The styling class sometimes sits directly on the <td> (index/property-name/null/truncated/
        // error columns) rather than on a nested <span> — see DumpRenderer's dp-propname/dp-number/
        // dp-null/dp-truncated td's.
        return StyledText(cls, td.Value) ?? Combine(td.Nodes().Select(RenderNode));
    }

    private static IRenderable Combine(IEnumerable<IRenderable?> renderables)
    {
        var list = renderables.Where(r => r is not null).Select(r => r!).ToList();
        return list.Count switch
        {
            0 => new Markup(string.Empty),
            1 => list[0],
            _ => new Rows(list),
        };
    }
}
